<?php require __DIR__.'/_data.php'; api_init(); $b=api_body(); if(empty($b['unit_id'])||empty($b['stock_arrival_date']))api_json(['status'=>'error','message'=>'unit_id and stock_arrival_date are required'],400);$d=date_create((string)$b['stock_arrival_date']);if(!$d)api_json(['status'=>'error','message'=>'Invalid date format (expected YYYY-MM-DD)'],400);$s=$d->format('Y-m-d');$st=db()->prepare('UPDATE storage_units SET stock_arrival_date=? WHERE id=?');$st->execute([$s,(int)$b['unit_id']]);$u=unit_row((int)$b['unit_id']);if(!$u)api_json(['status'=>'error','message'=>'Unit not found'],404);api_json(['status'=>'success','message'=>'Stock arrival date updated for Unit #'.$b['unit_id'],'data'=>forecast(['unit_id'=>$u['id'],'name'=>$u['name'],'location'=>$u['city'].', '.$u['state'],'grain_type'=>$u['grain_type'],'current_stock_tonnes'=>$u['current_stock_tonnes'],'moisture_pct'=>$u['moisture_pct'],'temp_c'=>27.5,'stock_arrival_date'=>$s,'facility_type'=>'Modern Steel Silo'])]);
